// 7) after a Lineup message: who wrote back, and was he answered? (owner 22 Nov: "thank you / ok" need no answer - they are left out). Counts only, no customer text. The reply is the customer's first message after his last Lineup message today.
try { try { $pdo->exec("SET SESSION MAX_EXECUTION_TIME = 100000"); } catch (Throwable $e) { } $pl = []; foreach ($pdo->query("SELECT phone, MAX(sent_at) s FROM wa_line_plan WHERE status = 'sent' AND sent_at >= '" . $t0 . "' GROUP BY phone")->fetchAll(PDO::FETCH_NUM) as $r) $pl[(string)$r[0]] = (string)$r[1];
    $triv = '/^\W*(ok+|okay|okk+|k|thanks?|thank you|thanku|thx|ty|done|got it|noted|fine|nice|good|great|cool|welcome|hmm+|haan?|ha|ji|jee|yes|yeah|theek( hai)?|thik( hai)?|sure|shukriya|dhanyawad|धन्यवाद|शुक्रिया|ठीक( है)?|हाँ|हां|जी|ओके|ok thanks|thank you so much)\W*$/iu';
    $n = ['replied' => 0, 'trivial' => 0, 'real' => 0, 'bot' => 0, 'emp' => 0, 'other' => 0, 'none30' => 0, 'none_now' => 0]; $dly = []; $ids = array_keys($pl);
